// These are the declarations of golang.org/x/image/draw v0.33.0 that
// CatmullRom.Scale runs (from scale.go, and impl.go, generated by its
// gen.go), copied verbatim: the kernel scaler and the scaleX/scaleY paths
// for the source images imgcache decodes and an *image.RGBA destination.
//
// Clack: Scale draws exactly what x/image's
// CatmullRom.Scale(dst, dst.Bounds(), src, sr, draw.Src, nil) draws, every
// pixel bit for bit, but a band of destination rows at a time. x/image
// scales every source row across to the destination's width first, into a
// temporary buffer of dw×sh entries of 32 bytes (a 24 MP photo scaled to
// 2048 px: 262 MB), then down. Here the buffer holds only the source rows
// the band's destination rows read, sliding down the image with them
// (a few MB), and the buffer and the kernel's weights are charged to the
// caller's budget.Budget before they're made. Every destination pixel is
// still the same sum, in the same order, of the same terms. Every changed
// line is marked Clack: (see ../CLACK_PATCHES.md). The weights and the band
// are given back to the budget (Free) when Scale returns.
package catmullrom

import (
	"image"
	"image/draw"
	"math"
	"unsafe"

	"github.com/some-du6e/clack/internal/imgcache/internal/budget"
)

var (
	// CatmullRom is the Catmull-Rom kernel. It is very slow, but usually gives
	// very high quality results.
	//
	// It is an instance of the more general cubic BC-spline kernel with parameters
	// B=0 and C=0.5. See Mitchell and Netravali, "Reconstruction Filters in
	// Computer Graphics", Computer Graphics, Vol. 22, No. 4, pp. 221-228.
	CatmullRom = &Kernel{2, func(t float64) float64 {
		if t < 1 {
			return float64((float64(1.5*t)-2.5)*t*t) + 1
		}
		return float64((float64(float64(float64(-0.5*t)+2.5)*t)-4)*t) + 2
	}}
)

// Kernel is an interpolator that blends source pixels weighted by a symmetric
// kernel function.
type Kernel struct {
	// Support is the kernel support and must be >= 0. At(t) is assumed to be
	// zero when t >= Support.
	Support float64
	// At is the kernel function. It will only be called with t in the
	// range [0, Support).
	At func(t float64) float64
}

type kernelScaler struct {
	kernel               *Kernel
	dw, dh, sw, sh       int32
	horizontal, vertical distrib
	// Clack: no pool and no makeTmpBuf: Scale makes one band's buffer
}

// source is a range of contribs, their inverse total weight, and that ITW
// divided by 0xffff.
type source struct {
	i, j               int32
	invTotalWeight     float64
	invTotalWeightFFFF float64
}

// contrib is the weight of a column or row.
type contrib struct {
	coord  int32
	weight float64
}

// distrib measures how source pixels are distributed over destination pixels.
type distrib struct {
	// sources are what contribs each column or row in the source image owns,
	// and the total weight of those contribs.
	sources []source
	// contribs are the contributions indexed by sources[s].i and sources[s].j.
	contribs []contrib
}

// newDistrib returns a distrib that distributes sw source columns (or rows)
// over dw destination columns (or rows).
//
// Clack: its two slices are charged to bg first.
func newDistrib(q *Kernel, dw, sw int32, bg *budget.Budget) (distrib, error) {
	scale := float64(sw) / float64(dw)
	halfWidth, kernelArgScale := q.Support, 1.0
	// When shrinking, broaden the effective kernel support so that we still
	// visit every source pixel.
	if scale > 1 {
		halfWidth *= scale
		kernelArgScale = 1 / scale
	}

	// Make the sources slice, one source for each column or row, and temporarily
	// appropriate its elements' fields so that invTotalWeight is the scaled
	// coordinate of the source column or row, and i and j are the lower and
	// upper bounds of the range of destination columns or rows affected by the
	// source column or row.
	if err := bg.Charge(int64(dw) * sourceBytes); err != nil { // Clack
		return distrib{}, err
	}
	n, sources := int32(0), make([]source, dw)
	for x := range sources {
		center := float64((float64(x)+0.5)*scale) - 0.5
		i := int32(math.Floor(center - halfWidth))
		if i < 0 {
			i = 0
		}
		j := int32(math.Ceil(center + halfWidth))
		if j > sw {
			j = sw
			if j < i {
				j = i
			}
		}
		sources[x] = source{i: i, j: j, invTotalWeight: center}
		n += j - i
	}

	if err := bg.Charge(int64(n) * contribBytes); err != nil { // Clack
		return distrib{}, err
	}
	contribs := make([]contrib, 0, n)
	for k, b := range sources {
		totalWeight := 0.0
		l := int32(len(contribs))
		for coord := b.i; coord < b.j; coord++ {
			t := abs((b.invTotalWeight - float64(coord)) * kernelArgScale)
			if t >= q.Support {
				continue
			}
			weight := q.At(t)
			if weight == 0 {
				continue
			}
			totalWeight += weight
			contribs = append(contribs, contrib{coord, weight})
		}
		totalWeight = 1 / totalWeight
		sources[k] = source{
			i:                  l,
			j:                  int32(len(contribs)),
			invTotalWeight:     totalWeight,
			invTotalWeightFFFF: totalWeight / 0xffff,
		}
	}

	return distrib{sources, contribs}, nil // Clack
}

// abs is like math.Abs, but it doesn't care about negative zero, infinities or
// NaNs.
func abs(f float64) float64 {
	if f < 0 {
		f = -f
	}
	return f
}

// ftou converts the range [0.0, 1.0] to [0, 0xffff].
func ftou(f float64) uint16 {
	i := int32(float64(0xffff*f) + 0.5)
	if i > 0xffff {
		return 0xffff
	}
	if i > 0 {
		return uint16(i)
	}
	return 0
}

// Scale draws src's sr scaled to the whole of dst, exactly as x/image/draw's
// CatmullRom.Scale(dst, dst.Bounds(), src, sr, draw.Src, nil) does (its
// kernelScaler.Scale, for Src and no options), a band of destination rows
// at a time. What it allocates (the kernel's weights, the band's buffer) is
// charged to b first: it fails with b's error, having drawn nothing, when
// they don't fit.
//
// Clack: this replaces kernelScaler.Scale.
func Scale(dst *image.RGBA, src image.Image, sr image.Rectangle, b *budget.Budget) error {
	dr := dst.Bounds()
	// adr is the affected destination pixels.
	adr := dst.Bounds().Intersect(dr)
	if adr.Empty() || sr.Empty() {
		return nil
	}
	// Make adr relative to dr.Min.
	adr = adr.Sub(dr.Min)

	if _, ok := src.(*image.Uniform); ok && sr.In(src.Bounds()) {
		draw.Draw(dst, dr, src, src.Bounds().Min, draw.Src)
		return nil
	}

	q := CatmullRom
	z := &kernelScaler{
		kernel: q,
		dw:     int32(dr.Dx()),
		dh:     int32(dr.Dy()),
		sw:     int32(sr.Dx()),
		sh:     int32(sr.Dy()),
	}
	// Clack: what Scale charges is garbage once it returns: given back then
	used := b.Used()
	defer func() { b.Free(b.Used() - used) }()
	var err error
	if z.horizontal, err = newDistrib(q, z.dw, z.sw, b); err != nil {
		return err
	}
	if z.vertical, err = newDistrib(q, z.dh, z.sh, b); err != nil {
		return err
	}

	// sr is the source pixels. If it extends beyond the src bounds,
	// we cannot use the type-specific fast paths, as they access
	// the Pix fields directly without bounds checking.
	scaleX := func(tmp [][4]float64, y0, y1 int32) { z.scaleX_Image(tmp, src, sr, y0, y1) }
	if sr.In(src.Bounds()) {
		switch src := src.(type) {
		case *image.Gray:
			scaleX = func(tmp [][4]float64, y0, y1 int32) { z.scaleX_Gray(tmp, src, sr, y0, y1) }
		case *image.NRGBA:
			scaleX = func(tmp [][4]float64, y0, y1 int32) { z.scaleX_NRGBA(tmp, src, sr, y0, y1) }
		case *image.RGBA:
			scaleX = func(tmp [][4]float64, y0, y1 int32) { z.scaleX_RGBA(tmp, src, sr, y0, y1) }
		case *image.YCbCr:
			switch src.SubsampleRatio {
			case image.YCbCrSubsampleRatio444:
				scaleX = func(tmp [][4]float64, y0, y1 int32) { z.scaleX_YCbCr444(tmp, src, sr, y0, y1) }
			case image.YCbCrSubsampleRatio422:
				scaleX = func(tmp [][4]float64, y0, y1 int32) { z.scaleX_YCbCr422(tmp, src, sr, y0, y1) }
			case image.YCbCrSubsampleRatio420:
				scaleX = func(tmp [][4]float64, y0, y1 int32) { z.scaleX_YCbCr420(tmp, src, sr, y0, y1) }
			case image.YCbCrSubsampleRatio440:
				scaleX = func(tmp [][4]float64, y0, y1 int32) { z.scaleX_YCbCr440(tmp, src, sr, y0, y1) }
			}
		case image.RGBA64Image:
			scaleX = func(tmp [][4]float64, y0, y1 int32) { z.scaleX_RGBA64Image(tmp, src, sr, y0, y1) }
		}
	}

	// The destination rows go in bands of rows; tmp holds the source rows
	// the band's rows read, scaled across, and keeps those the next band
	// reads too. It's as big as the most rows a band reads.
	rows := bandRows(z.dh, z.sh)
	most := int32(0)
	for y := int32(adr.Min.Y); y < int32(adr.Max.Y); y += rows {
		if lo, hi, ok := z.vertical.span(y, min(y+rows, int32(adr.Max.Y))); ok {
			most = max(most, hi-lo)
		}
	}
	if err := b.Charge(int64(most) * int64(z.dw) * tmpEntryBytes); err != nil {
		return err
	}
	tmp := make([][4]float64, int(most)*int(z.dw))
	dw := int(z.dw)
	have0, have1 := int32(0), int32(0) // the source rows in tmp
	for y := int32(adr.Min.Y); y < int32(adr.Max.Y); y += rows {
		y1 := min(y+rows, int32(adr.Max.Y))
		lo, hi, ok := z.vertical.span(y, y1)
		if !ok { // its rows read no source row
			lo, hi = have0, have0
		} else {
			from := lo
			if lo >= have0 && lo < have1 { // rows the last band read too stay
				keep := min(have1, hi)
				copy(tmp, tmp[int(lo-have0)*dw:int(keep-have0)*dw])
				from = keep
			}
			if from < hi {
				scaleX(tmp[int(from-lo)*dw:int(hi-lo)*dw], from, hi)
			}
			have0, have1 = lo, hi
		}
		z.scaleY_RGBA_Src(dst, dr, image.Rect(adr.Min.X, int(y), adr.Max.X, int(y1)), tmp, lo)
	}
	return nil
}

// span is the source rows (or columns) the contribs of destination rows y0
// to y1 read: lo to hi; ok is false when they read none.
func (d *distrib) span(y0, y1 int32) (lo, hi int32, ok bool) {
	for _, s := range d.sources[y0:y1] {
		for _, c := range d.contribs[s.i:s.j] {
			if !ok || c.coord < lo {
				lo = c.coord
			}
			if !ok || c.coord >= hi {
				hi = c.coord + 1
			}
			ok = true
		}
	}
	return lo, hi, ok
}

// bandRows is how many destination rows a band holds: bandSource source
// rows' worth at the scale (at least one, at most them all).
func bandRows(dh, sh int32) int32 {
	r := int64(bandSource) * int64(dh) / int64(max(sh, 1))
	return int32(max(1, min(r, int64(dh))))
}

// bandSource is about how many source rows a band covers, besides the
// kernel's reach above and below it (2 rows each way, times the scale when
// shrinking).
const bandSource = 32

// The sizes Scale charges: a source, a contrib and a tmp entry, as Go lays
// them out (budget_test.go checks they're what x/image's are).
const (
	sourceBytes   = int64(unsafe.Sizeof(source{}))
	contribBytes  = int64(unsafe.Sizeof(contrib{}))
	tmpEntryBytes = int64(unsafe.Sizeof([4]float64{}))
)

// Clack: rows y0 to y1 of sr into tmp (x/image's scaled all sh of them).
func (z *kernelScaler) scaleX_Gray(tmp [][4]float64, src *image.Gray, sr image.Rectangle, y0, y1 int32) {
	t := 0
	for y := y0; y < y1; y++ { // Clack: was 0 to z.sh
		for _, s := range z.horizontal.sources {
			var pr float64
			for _, c := range z.horizontal.contribs[s.i:s.j] {
				pi := (sr.Min.Y+int(y)-src.Rect.Min.Y)*src.Stride + (sr.Min.X + int(c.coord) - src.Rect.Min.X)
				pru := uint32(src.Pix[pi]) * 0x101
				pr += float64(float64(pru) * c.weight)
			}
			pr *= s.invTotalWeightFFFF
			tmp[t] = [4]float64{
				pr,
				pr,
				pr,
				1,
			}
			t++
		}
	}
}

// Clack: rows y0 to y1 of sr into tmp (x/image's scaled all sh of them).
func (z *kernelScaler) scaleX_NRGBA(tmp [][4]float64, src *image.NRGBA, sr image.Rectangle, y0, y1 int32) {
	t := 0
	for y := y0; y < y1; y++ { // Clack: was 0 to z.sh
		for _, s := range z.horizontal.sources {
			var pr, pg, pb, pa float64
			for _, c := range z.horizontal.contribs[s.i:s.j] {
				pi := (sr.Min.Y+int(y)-src.Rect.Min.Y)*src.Stride + (sr.Min.X+int(c.coord)-src.Rect.Min.X)*4
				pau := uint32(src.Pix[pi+3]) * 0x101
				pru := uint32(src.Pix[pi+0]) * pau / 0xff
				pgu := uint32(src.Pix[pi+1]) * pau / 0xff
				pbu := uint32(src.Pix[pi+2]) * pau / 0xff
				pr += float64(float64(pru) * c.weight)
				pg += float64(float64(pgu) * c.weight)
				pb += float64(float64(pbu) * c.weight)
				pa += float64(float64(pau) * c.weight)
			}
			tmp[t] = [4]float64{
				pr * s.invTotalWeightFFFF,
				pg * s.invTotalWeightFFFF,
				pb * s.invTotalWeightFFFF,
				pa * s.invTotalWeightFFFF,
			}
			t++
		}
	}
}

// Clack: rows y0 to y1 of sr into tmp (x/image's scaled all sh of them).
